{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.MongLong0214/logic-pro-mcp",
  "title": "Logic Pro MCP",
  "description": "Logic Pro MCP server for stateful DAW control, live readback, MIDI, plugins, and safety gates.",
  "websiteUrl": "https://github.com/MongLong0214/logic-pro-mcp#readme",
  "repository": {
    "url": "https://github.com/MongLong0214/logic-pro-mcp",
    "source": "github"
  },
  "icons": [
    {
      "src": "https://raw.githubusercontent.com/MongLong0214/logic-pro-mcp/main/docs/media/logic-pro-mcp-thumbnail.png",
      "mimeType": "image/png",
      "sizes": [
        "1200x630"
      ]
    }
  ],
  "version": "3.11.0",
  "_meta": {
    "io.modelcontextprotocol.registry/publisher-provided": {
      "distribution": {
        "status": "metadata-only",
        "homebrew": {
          "tap": "MongLong0214/logic-pro-mcp",
          "formula": "logic-pro-mcp",
          "install": [
            "brew tap MongLong0214/logic-pro-mcp https://github.com/MongLong0214/logic-pro-mcp",
            "brew trust monglong0214/logic-pro-mcp",
            "brew install logic-pro-mcp"
          ]
        },
        "release": "https://github.com/MongLong0214/logic-pro-mcp/releases/tag/v3.11.0",
        "directories": {
          "lobeHub": "https://lobehub.com/mcp/monglong0214-logic-pro-mcp",
          "pulseMCP": "https://www.pulsemcp.com/servers/monglong-logic-pro"
        }
      },
      "discovery": {
        "categories": [
          "Music production",
          "Desktop automation",
          "macOS",
          "Developer tools",
          "Agent tools"
        ],
        "tags": [
          "logic-pro",
          "music-production",
          "audio-production",
          "daw",
          "daw-automation",
          "macos",
          "swift",
          "mcp",
          "model-context-protocol",
          "ai-agents",
          "ai-music",
          "automation",
          "app-automation",
          "desktop-automation",
          "logic-pro-x",
          "claude",
          "claude-code",
          "cursor",
          "midi",
          "mcp-server",
          "music-tech"
        ]
      },
      "runtime": {
        "transport": "stdio",
        "command": "LogicProMCP",
        "clientConfig": {
          "mcpServers": {
            "logic-pro": {
              "command": "LogicProMCP"
            }
          }
        }
      },
      "requirements": {
        "platform": "macOS 14+ for the MCP server; Logic Pro 12.3 requires macOS 15.6+",
        "logicPro": "12.3 first-class validation target; 12.0.1+ best-effort floor; supports desktop (com.apple.logic10) and Creator Studio (com.apple.mobilelogic)",
        "permissions": [
          "Accessibility",
          "Automation"
        ]
      },
      "capabilities": {
        "tools": 10,
        "resources": 18,
        "resourceTemplates": 11,
        "controlChannels": [
          "MCU",
          "Accessibility",
          "AppleScript",
          "CoreMIDI",
          "CGEvent",
          "Scripter",
          "MIDI Key Commands"
        ]
      },
      "registryFit": "Official package types do not currently include Homebrew formulas or GitHub release tarballs, so this record intentionally relies on websiteUrl plus publisher metadata."
    }
  }
}
